def cap_epochs(weights, unique, budget, max_epochs=4.0):
    """Cap each domain at max_epochs; give the freed tokens to the rest
    in proportion to their weights. Returns new weights summing to 1."""
    fixed = {}                                   # domain: tokens, capped
    while True:
        free = {d: w for d, w in weights.items() if d not in fixed}
        left = budget - sum(fixed.values())
        total = sum(free.values())
        over = [d for d, w in free.items()
                if w / total * left > max_epochs * unique[d]]
        if not over:
            tokens = {**fixed, **{d: w / total * left for d, w in free.items()}}
            return {d: tokens[d] / budget for d in weights}
        for d in over:
            fixed[d] = max_epochs * unique[d]

unique = {"web": 100e9, "wiki": 2e9, "code": 50e9, "papers": 1e9}   # tokens
learned = {"web": 0.60, "wiki": 0.20, "code": 0.15, "papers": 0.05}
budget = 200e9
for d, w in learned.items():
    print(f"{d:6s} learned {w:.2f} = {w * budget / unique[d]:5.1f} epochs")
capped = cap_epochs(learned, unique, budget)
for d, w in capped.items():
    print(f"{d:6s} capped  {w:.3f} = {w * budget / unique[d]:5.2f} epochs")

